1	import 'package:cerne/features/vault/domain/entities/biometric_capability.dart';
2	import 'package:cerne/features/vault/domain/entities/vault_entry_mode.dart';
3	import 'package:cerne/features/vault/domain/repositories/vault_repository.dart';
4	import 'package:cerne/features/vault/domain/usecases/determine_vault_entry_usecase.dart';
5	import 'package:cerne/features/vault/domain/usecases/save_biometrics_preference_usecase.dart';
6	import 'package:cerne/features/vault/domain/usecases/save_pin_usecase.dart';
7	import 'package:cerne/features/vault/domain/usecases/verify_pin_usecase.dart';
8	import 'package:cerne/features/vault/presentation/bloc/vault_event.dart';
9	import 'package:cerne/features/vault/presentation/bloc/vault_state.dart';
10	import 'package:flutter_bloc/flutter_bloc.dart';
11	
12	const _biometricFailureMessage = 'Não foi possível reconhecer — digite seu PIN';
13	
14	/// Screen-scoped bloc backing the single `VaultPage` (research.md R4):
15	/// first-time PIN setup, biometric unlock, PIN-fallback unlock, and the
16	/// biometrics opt-in, all as sub-states of one bloc.
17	class VaultBloc extends Bloc<VaultEvent, VaultState> {
18	  VaultBloc({
19	    required this._determineVaultEntryUseCase,
20	    required this._verifyPinUseCase,
21	    required this._savePinUseCase,
22	    required this._saveBiometricsPreferenceUseCase,
23	    required this._repository,
24	  }) : super(const VaultInitial()) {
25	    on<VaultOpened>(_onVaultOpened);
26	    on<BiometricAuthRequested>(_onBiometricAuthRequested);
27	    on<PinDigitEntered>(_onPinDigitEntered);
28	    on<PinBackspacePressed>(_onPinBackspacePressed);
29	    on<PinSubmitted>(_onPinSubmitted);
30	    on<BiometricOptInToggled>(_onBiometricOptInToggled);
31	  }
32	
33	  final DetermineVaultEntryUseCase _determineVaultEntryUseCase;
34	  final VerifyPinUseCase _verifyPinUseCase;
35	  final SavePinUseCase _savePinUseCase;
36	  final SaveBiometricsPreferenceUseCase _saveBiometricsPreferenceUseCase;
37	  final VaultRepository _repository;
38	
39	  Future<void> _onVaultOpened(
40	    VaultOpened event,
41	    Emitter<VaultState> emit,
42	  ) async {
43	    final mode = await _determineVaultEntryUseCase();
44	    switch (mode) {
45	      case VaultEntryMode.pinSetupRequired:
46	        emit(const VaultPinSetupCreate());
47	      case VaultEntryMode.unlockBiometricFirst:
48	        emit(const VaultBiometricPrompting());
49	        await _performBiometricAuth(emit);
50	      case VaultEntryMode.unlockPinOnly:
51	        emit(const VaultPinEntry());
52	    }
53	  }
54	
55	  Future<void> _onBiometricAuthRequested(
56	    BiometricAuthRequested event,
57	    Emitter<VaultState> emit,
58	  ) async {
59	    emit(const VaultBiometricPrompting());
60	    await _performBiometricAuth(emit);
61	  }
62	
63	  Future<void> _performBiometricAuth(Emitter<VaultState> emit) async {
64	    final outcome = await _repository.attemptBiometricAuth();
65	    if (outcome == BiometricAuthOutcome.success) {
66	      _repository.markUnlocked(DateTime.now());
67	      emit(const VaultUnlocked());
68	      return;
69	    }
70	    // failed / cancelled / notAvailable are all routed identically (FR-004
71	    // does not distinguish them) — contracts/vault-repository.md.
72	    emit(const VaultPinEntry(errorMessage: _biometricFailureMessage));
73	  }
74	
75	  void _onPinDigitEntered(PinDigitEntered event, Emitter<VaultState> emit) {
76	    final current = state;
77	    switch (current) {
78	      case VaultPinSetupCreate(:final enteredDigits):
79	        final next = enteredDigits + event.digit;
80	        if (next.length < 4) {
81	          emit(VaultPinSetupCreate(enteredDigits: next));
82	        } else {
83	          emit(VaultPinSetupConfirm(firstPin: next));
84	        }
85	      case VaultPinSetupConfirm(:final firstPin, :final enteredDigits):
86	        final next = enteredDigits + event.digit;
87	        if (next.length < 4) {
88	          emit(VaultPinSetupConfirm(firstPin: firstPin, enteredDigits: next));
89	        } else {
90	          emit(VaultPinSetupConfirm(firstPin: firstPin, enteredDigits: next));
91	          add(const PinSubmitted());
92	        }
93	      case VaultPinEntry(:final enteredDigits, :final errorMessage):
94	        final next = enteredDigits + event.digit;
95	        if (next.length < 4) {
96	          emit(VaultPinEntry(enteredDigits: next, errorMessage: errorMessage));
97	        } else {
98	          emit(VaultPinEntry(enteredDigits: next, errorMessage: errorMessage));
99	          add(const PinSubmitted());
100	        }
101	      case VaultInitial():
102	      case VaultBiometricOptIn():
103	      case VaultBiometricPrompting():
104	      case VaultUnlocked():
105	        break;
106	    }
107	  }
108	
109	  void _onPinBackspacePressed(
110	    PinBackspacePressed event,
111	    Emitter<VaultState> emit,
112	  ) {
113	    final current = state;
114	    switch (current) {
115	      case VaultPinSetupCreate(:final enteredDigits):
116	        if (enteredDigits.isNotEmpty) {
117	          emit(
118	            VaultPinSetupCreate(
119	              enteredDigits: enteredDigits.substring(
120	                0,
121	                enteredDigits.length - 1,
122	              ),
123	            ),
124	          );
125	        }
126	      case VaultPinSetupConfirm(:final firstPin, :final enteredDigits):
127	        if (enteredDigits.isNotEmpty) {
128	          emit(
129	            VaultPinSetupConfirm(
130	              firstPin: firstPin,
131	              enteredDigits: enteredDigits.substring(
132	                0,
133	                enteredDigits.length - 1,
134	              ),
135	            ),
136	          );
137	        }
138	      case VaultPinEntry(:final enteredDigits, :final errorMessage):
139	        if (enteredDigits.isNotEmpty) {
140	          emit(
141	            VaultPinEntry(
142	              enteredDigits: enteredDigits.substring(
143	                0,
144	                enteredDigits.length - 1,
145	              ),
146	              errorMessage: errorMessage,
147	            ),
148	          );
149	        }
150	      case VaultInitial():
151	      case VaultBiometricOptIn():
152	      case VaultBiometricPrompting():
153	      case VaultUnlocked():
154	        break;
155	    }
156	  }
157	
158	  Future<void> _onPinSubmitted(
159	    PinSubmitted event,
160	    Emitter<VaultState> emit,
161	  ) async {
162	    final current = state;
163	    switch (current) {
164	      case VaultPinSetupConfirm(:final firstPin, :final enteredDigits):
165	        if (enteredDigits != firstPin) {
166	          emit(
167	            const VaultPinSetupCreate(
168	              mismatchMessage: 'Os PINs não coincidem. Tente novamente.',
169	            ),
170	          );
171	          return;
172	        }
173	        await _savePinUseCase(firstPin);
174	        final capability = await _repository.checkBiometricCapability();
175	        if (capability == BiometricCapability.available) {
176	          emit(const VaultBiometricOptIn());
177	        } else {
178	          _repository.markUnlocked(DateTime.now());
179	          emit(const VaultUnlocked());
180	        }
181	      case VaultPinEntry(:final enteredDigits, :final errorMessage):
182	        final correct = await _verifyPinUseCase(enteredDigits);
183	        if (correct) {
184	          _repository.markUnlocked(DateTime.now());
185	          emit(const VaultUnlocked());
186	        } else {
